import{_ as e,o as a,c as i,ae as o}from"./chunks/framework.Co1PSFSm.js";const u=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"docs/getting-started.md","filePath":"docs/getting-started.md"}'),r={name:"docs/getting-started.md"};function n(s,t,l,c,d,p){return a(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>Welcome to the <strong>CM Transcription Equivalents</strong> user manual.</p><h2 id="what-is-this-tool" tabindex="-1">What is this tool? <a class="header-anchor" href="#what-is-this-tool" aria-label="Permalink to &quot;What is this tool?&quot;">​</a></h2><p><strong>CM Transcription Equivalents</strong> is a specialized, lightweight research application designed specifically for <strong>musicologists</strong> working with medieval chant manuscripts and digital transcriptions.</p><p>When analyzing chant repertoires, scholars often need to bridge the gap between abstract melodic data (e.g., modern transcriptions, MEI data, Volpiano) and the physical graphical reality of the medieval manuscript. This tool allows you to:</p><ol><li>Identify and categorize reoccurring neume patterns in your transcription data.</li><li>Link those abstract patterns directly to specific ink strokes on high-resolution IIIF manuscript scans.</li><li>Establish a standard typology (Reference IDs) for graphical signs across different manuscript sources.</li><li>Generate interactive, public-facing documentation of your notation analysis.</li></ol><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>A modern web browser (Chrome, Firefox, Safari).</li><li>Access to IIIF manifests for the manuscripts you wish to annotate (usually provided by library archives).</li><li>Transcription data in a supported JSON format (exported from your primary transcription environment).</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><p>The tool is primarily a web application. You can run it locally:</p><ol><li>Clone the repository to your local machine.</li><li>Navigate to the <code>ui</code> directory in your terminal.</li><li>Run <code>npm install</code> to install dependencies.</li><li>Run <code>npm run dev</code> to start the local development server.</li><li>Open the provided <code>localhost</code> URL in your browser.</li></ol><p>Next, read about the <a href="./conventions.html">Conventions &amp; Terminology</a> used in this application.</p>',12)])])}const m=e(r,[["render",n]]);export{u as __pageData,m as default};
